import{_ as e,c as o,o as a,a0 as n}from"./chunks/framework.oTSD2LDJ.js";const h=JSON.parse('{"title":"Component Encyclopedia","description":"","frontmatter":{"title":"Component Encyclopedia","editLink":true},"headers":[],"relativePath":"en/component-encyclopedia/overview.md","filePath":"en/component-encyclopedia/overview.md"}'),r={name:"en/component-encyclopedia/overview.md"};function d(i,t,c,l,p,s){return a(),o("div",null,t[0]||(t[0]=[n('<h1 id="component-encyclopedia" tabindex="-1">Component Encyclopedia <a class="header-anchor" href="#component-encyclopedia" aria-label="Permalink to &quot;Component Encyclopedia&quot;">​</a></h1><p>Uniquenium components fall into two categories: <strong>built-in components (UDC-prefixed)</strong> and <strong>official plugin components</strong>. Built-in components work out of the box; plugin components require the official plugin pack.</p><h2 id="built-in-components" tabindex="-1">Built-in Components <a class="header-anchor" href="#built-in-components" aria-label="Permalink to &quot;Built-in Components&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Description</th></tr></thead><tbody><tr><td><a href="./UDCText">UDCText</a></td><td>Text display with <code>%{}</code> expression support for dynamic data</td></tr><tr><td><a href="./UDCImage">UDCImage</a></td><td>Image display with rounded corners and button actions</td></tr><tr><td><a href="./UDCFrame">UDCFrame</a></td><td>Decorative frame/container for layout separation</td></tr></tbody></table><h2 id="official-plugin-components" tabindex="-1">Official Plugin Components <a class="header-anchor" href="#official-plugin-components" aria-label="Permalink to &quot;Official Plugin Components&quot;">​</a></h2><p>The official plugin pack provides many more components: system monitors, weather, calendar, media player, quick notes, etc.</p><p>For the full list and installation, see <a href="./../official-plugins">Official Plugins</a>.</p><h2 id="common-properties" tabindex="-1">Common Properties <a class="header-anchor" href="#common-properties" aria-label="Permalink to &quot;Common Properties&quot;">​</a></h2><p>All UDC components inherit from <code>UniDeskComBase</code> and share these common properties:</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>visible</code></td><td>bool</td><td>Whether the component is visible</td></tr><tr><td><code>width</code></td><td>real</td><td>Component width</td></tr><tr><td><code>height</code></td><td>real</td><td>Component height</td></tr><tr><td><code>x</code></td><td>real</td><td>X coordinate</td></tr><tr><td><code>y</code></td><td>real</td><td>Y coordinate</td></tr><tr><td><code>itemOpacity</code></td><td>real</td><td>Opacity (0.0 ~ 1.0)</td></tr><tr><td><code>identification</code></td><td>string</td><td>Unique component ID</td></tr><tr><td><code>parentIdentification</code></td><td>string</td><td>Parent component ID</td></tr></tbody></table><h2 id="common-methods" tabindex="-1">Common Methods <a class="header-anchor" href="#common-methods" aria-label="Permalink to &quot;Common Methods&quot;">​</a></h2><h3 id="propertydataex-→-object" tabindex="-1"><code>propertyDataEx() → object</code> <a class="header-anchor" href="#propertydataex-→-object" aria-label="Permalink to &quot;`propertyDataEx() → object`&quot;">​</a></h3><p>Exports the component&#39;s custom property data as a JSON object (for template saving).</p><h3 id="loadpropertydataex-data" tabindex="-1"><code>loadPropertyDataEx(data)</code> <a class="header-anchor" href="#loadpropertydataex-data" aria-label="Permalink to &quot;`loadPropertyDataEx(data)`&quot;">​</a></h3><p>Loads custom property data from a JSON object (for template loading).</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../controls-reference/overview">Controls Reference</a> — UniDesk controls system</li><li><a href="./../controls-reference/singletons/UniDeskComManager">UniDeskComManager</a> — Component manager</li><li><a href="./../official-plugins">Official Plugins</a> — Plugin component list</li></ul>',17)]))}const f=e(r,[["render",d]]);export{h as __pageData,f as default};
